WITH src AS (SELECT * FROM employees WHERE dept_id = 12 AND email LIKE '%@mail.co.th'), employees_stats AS (SELECT CASE WHEN salary >= 129000 THEN 'high' WHEN salary >= 62000 THEN 'mid' ELSE 'low' END AS salary_bucket, is_remote, SUM(CASE WHEN level = 'L3' THEN salary ELSE 0 END) AS l3_salary FROM src GROUP BY CASE WHEN salary >= 129000 THEN 'high' WHEN salary >= 62000 THEN 'mid' ELSE 'low' END, is_remote) SELECT salary_bucket, l3_salary FROM employees_stats ORDER BY l3_salary DESC, salary_bucket
